import json, time, math
from urllib.request import Request, urlopen
from urllib.error import HTTPError, URLError
from datetime import datetime, timezone

BASE='http://localhost:8080'
token=None
customer_cache={}

def token_new():
    global token
    req=Request(BASE+'/token',method='POST')
    with urlopen(req,timeout=15) as x: token=[REDACTED_SECRET]'token']

def retry_after(headers, body):
    for key in ('Retry-After','retry-after'):
        v=headers.get(key)
        if v:
            try:return max(0.05,float(v))
            except:pass
    try:
        x=json.loads(body.decode())
        for k in ('retry_after','retry_after_seconds','wait_seconds'):
            if k in x:return max(0.05,float(x[k]))
    except:pass
    return 1

def get(path):
    global token
    attempts=0
    while True:
        attempts+=1
        if token is None: token_new()
        req=Request(BASE+path,headers={'Authorization':'Bearer '+token})
        try:
            with urlopen(req,timeout=20) as res: return json.load(res)
        except HTTPError as e:
            body=e.read()
            if e.code==401:
                token=None
                continue
            if e.code==429:
                time.sleep(retry_after(e.headers,body))
                continue
            if e.code>=500 and attempts<20:
                time.sleep(1)
                continue
            raise RuntimeError(f'GET {path}: HTTP {e.code} {body[:300]"'!r}'"')
        except (URLError,TimeoutError) as e:
            if attempts<20:
                time.sleep(1)
                continue
            raise

def customer(cid):
    if cid not in customer_cache: customer_cache[cid]=get('/customers/'+str(cid))
    return customer_cache[cid]

seen=set(); dups=0; qualifying=[]
page=1; total_pages=None
while total_pages is None or page<=total_pages:
    data=get('/orders?page='+str(page))
    if data['page']"'!=page: raise RuntimeError('"'page mismatch')
    total_pages=data['total_pages']
    for o in data['items']:
        if o['id'] in seen:
            dups+=1
            continue
        seen.add(o['id'])
        utc=datetime.fromisoformat(o['placed_at'].replace('Z','+00:00')).astimezone(timezone.utc)
        if (o['status']=='shipped' and datetime(2025,3,1,tzinfo=timezone.utc) <= utc < datetime(2025,6,1,tzinfo=timezone.utc)):
            qualifying.append(o)
    page+=1

by={x:0 for x in ('north','south','east','west')}
for o in qualifying:
    c=customer(o['customer_id'])
    # integer positive-cent half-up: floor(amount * (100-discount)/100 + .5)
    amt=(o['amount_cents']*(100-c['discount_pct'])*2 + 100)//200
    by[c['region']]+=amt
out={'total_cents':sum(by.values()),'order_count':len(qualifying),'duplicates_skipped':dups,'by_region':by}
print(json.dumps(out,sort_keys=True))
print('pages',total_pages,'listed_unique',len(seen),'customers',len(customer_cache),'qualifying',len(qualifying),file=__import__('sys').stderr)
